package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamLandformsBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun landformQuestions(): List<QSpec> {
    val t = "භූ රූප විද්‍යාව, පාෂාණ හා භූ තැටි චලනය"
    return listOf(
      q(t, "පෘථිවි අභ්‍යන්තරයේ උණු වූ මැග්මා හෝ ලාවා සිසිල් වී ඝන වීමෙන් නිර්මාණය වන ප්‍රාථමික පාෂාණ වර්ගය කුමක්ද?",
        "ආග්නේය පාෂාණ (Igneous Rocks)", "අවසාදිත පාෂාණ", "විපරීත පාෂාණ", "කාබනික පාෂාණ",
        "ග්‍රැනයිට් (Granite) හා බැසෝල්ට් (Basalt) ප්‍රධාන ආග්නේය පාෂාණ උදාහරණ වේ."),
      q(t, "පෘථිවි පෘෂ්ඨය මතට ගලා ආ ලාවා ඉක්මනින් සිසිල් වීමෙන් සෑදෙන සියුම් ස්ඵටික සහිත බාහිර ආග්නේය පාෂාණය කුමක්ද?",
        "බැසෝල්ට් (Basalt)", "ග්‍රැනයිට් (Granite)", "මැණික්", "කිරිගරුඬ",
        "සාගර කබොල ප්‍රධාන වශයෙන් බැසෝල්ට් පාෂාණවලින් සමන්විත වේ."),
      q(t, "පොළොව අභ්‍යන්තරයේ ගැඹුරේදී මැග්මා ඉතා සෙමින් සිසිල් වීම නිසා විශාල ස්ඵටික සහිතව සෑදෙන ආග්නේය පාෂාණය කුමක්ද?",
        "ග්‍රැනයිට් (Granite - අභ්‍යන්තර/Plutonic පාෂාණය)", "හුණුගල්", "බැසෝල්ට්", "ගල් අඟුරු",
        "මහාද්වීපික කබොලේ බහුලව ඇති ග්‍රැනයිට් පාෂාණයේ ක්වාර්ට්ස් සහ ෆෙල්ඩ්ස්පාර් ස්ඵටික පැහැදිලිව පෙනේ."),
      q(t, "විවිධ ඛාදන කාරක මගින් ගෙනෙන අවසාදිත ද්‍රව්‍ය ස්තර වශයෙන් තැන්පත් වී සම්පීඩනය වීමෙන් සෑදෙන පාෂාණ වර්ගය කුමක්ද?",
        "අවසාදිත පාෂාණ (Sedimentary Rocks)", "ආග්නේය පාෂාණ", "විපරීත පාෂාණ", "ලෝහමය පාෂාණ",
        "වැලිගල් (Sandstone), හුණුගල් (Limestone), ශේල් (Shale) සහ ගල් අඟුරු අවසාදිත පාෂාණ වේ."),
      q(t, "පෘථිවියේ අතීත ජීවීන්ගේ පොසිල (Fossils) සහ ඛනිජ තෙල්/ගල් අඟුරු බහුලව සුරැකී පවතින්නේ කුමන පාෂාණ වර්ගය තුළද?",
        "අවසාදිත පාෂාණ (Sedimentary Rocks)", "ආග්නේය පාෂාණ", "උල්කාපාත", "මැග්මා",
        "අවසාදිත පාෂාණ අධික තාපයකින් තොරව ස්තර වශයෙන් තැන්පත් වන නිසා පොසිල විනාශ නොවී ආරක්ෂා වේ."),
      q(t, "පවතින ආග්නේය හෝ අවසාදිත පාෂාණ පොළොව අභ්‍යන්තරයේ අධික තාපයට හා පීඩනයට ලක්වී දිය නොවී වෙනස් වීමෙන් සෑදෙන පාෂාණ කුමක්ද?",
        "විපරීත පාෂාණ (Metamorphic Rocks)", "ප්‍රාථමික පාෂාණ", "වැලි පාෂාණ", "ලාවා පාෂාණ",
        "ශ්‍රී ලංකාවේ භූමියෙන් 90% කට ආසන්න ප්‍රමාණයක් ප්‍රාග්-කේම්බ්‍රියානු විපරීත පාෂාණවලින් (Gneiss, Marble, Quartzite) සමන්විතය."),
      q(t, "හුණුගල් (Limestone) අධික තාපයට හා පීඩනයට ලක්වී විපරීත වීමෙන් සෑදෙන දැඩි විපරීත පාෂාණය කුමක්ද?",
        "කිරිගරුඬ (Marble)", "ස්ලේට් (Slate)", "ක්වාර්ට්සයිට්", "නයිස් (Gneiss)",
        "ඉදිකිරීම් හා මූර්ති කලාවට භාවිත කරන කිරිගරුඬ හුණුගල්වල විපරීත ස්වරූපයයි."),
      q(t, "මැටි පාෂාණයක් වන ශේල් (Shale) පීඩනයට ලක්වී විපරීත වීමෙන් වහල සෙවිලි කිරීමට පවා ගන්නා තුනී පතුරු සහිත පාෂාණය කුමක්ද?",
        "ස්ලේට් (Slate)", "කිරිගරුඬ", "බැසෝල්ට්", "හිරිගල්",
        "වැලිගල් (Sandstone) විපරීත වීමෙන් ක්වාර්ට්සයිට් (Quartzite) ද ග්‍රැනයිට් විපරීත වීමෙන් නයිස් (Gneiss) ද සෑදේ."),
      q(t, "විවිධ ඛනිජ වර්ගවල සීරීම් දෘඪතාව මැනීම සඳහා 'මෝස් දෘඪතා පරිමාණයේ' (Mohs Hardness Scale) උපරිම අගය වන 10 හිමි ඛනිජය කුමක්ද?",
        "දියමන්ති (Diamond)", "ටැල්ක් (Talc)", "ක්වාර්ට්ස්", "මිනිරන්",
        "ටැල්ක් අවම දෘඪතාව (1) හා දියමන්ති උපරිම දෘඪතාව (10) දරයි."),
      q(t, "ඇල්ෆ්‍රඩ් වෙගනර් (Alfred Wegener) විසින් 1912 දී ඉදිරිපත් කරන ලද මහාද්වීප අතීතයේදී එකට තිබී වෙන්වී ගිය බව පැවසෙන න්‍යාය කුමක්ද?",
        "මහාද්වීපික ප්ලාවිත න්‍යාය (Continental Drift Theory)", "මහා පිපිරුම් න්‍යාය", "කොරියෝලිස් න්‍යාය", "සමුද්‍ර දියවැල් න්‍යාය",
        "අතීතයේ සියලු මහාද්වීප එක්ව තිබූ සුපිරි මහාද්වීපය 'පැන්ජියා' (Pangaea) නම් විය."),
      q(t, "භූ තැටි (Tectonic Plates) පෘථිවි ප්‍රාවරණයේ ඉහළ අර්ධ-ද්‍රව ස්තරය (Asthenosphere) මත චලනය වීමට ශක්තිය සපයන ප්‍රධාන යාන්ත්‍රණය කුමක්ද?",
        "ප්‍රාවරණයේ සිදුවන තාප සංවහන ධාරා (Mantle Convection Currents)", "සාගර සුළං", "චන්ද්‍ර ගුරුත්වාකර්ෂණය", "මෝසම් වැසි",
        "අභ්‍යන්තර තාපය නිසා උණුසුම් ද්‍රව්‍ය ඉහළ නැග පැතිරී සිසිල් වී පහළ බැසීම භූ තැටි ගෙන යයි."),
      q(t, "භූ තැටි දෙකක් එකිනෙකින් ඉවතට ඇදී යන (අපසාරී - Divergent) සීමාවක ප්‍රධාන වශයෙන්ම නිර්මාණය වන භූ ලක්ෂණය කුමක්ද?",
        "මධ්‍ය සාගරික වැටි (Mid-Ocean Ridges) සහ විභේද නිම්න (Rift Valleys)", "හිමාලය වැනි නැමි කඳු", "සාගර අගාධ", "කොරල් දූපත්",
        "මධ්‍ය අත්ලාන්තික් වැටිය සහ නැගෙනහිර අප්‍රිකානු විභේද නිම්නය අපසාරී සීමාවන්ට උදාහරණ වේ."),
      q(t, "මහාද්වීපික භූ තැටි දෙකක් එකිනෙක ගැටෙන අභිසාරී (Convergent) සීමාවකදී නිර්මාණය වූ ප්‍රධානතම නැමි කඳු වැටිය (Fold Mountain) කුමක්ද?",
        "හිමාලය කඳු වැටිය (ඉන්දියානු තැටිය හා යුරේසියානු තැටිය ගැටීමෙන්)", "මධ්‍ය අත්ලාන්තික් වැටිය", "ෆුජි ගිනි කන්ද", "සැන් ඇන්ඩ්‍රියාස් විභේදනය",
